"use client";
import {CreateRecord} from "@/components/maintenance-records";
import type {SupabaseClient} from "@supabase/supabase-js";
const conversations:Record<string,string>[]=[],entries:Record<string,unknown[]>={};
const client={auth:{getSession:async()=>({data:{session:{access_token:"synthetic-test"}}})},rpc:async(_name:string,args:{p_action:string;p_payload:Record<string,string>})=>{const p=args.p_payload;let data:unknown=[];if(args.p_action==='conversations')data=conversations;if(args.p_action==='create_conversation'){const row={id:p.id,title:p.title,context_kind:p.contextKind,context_id:p.contextId,context_label:p.contextLabel,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};conversations.push(row);entries[p.id]=[];data=row;}if(args.p_action==='list')data=entries[p.conversationId]||[];if(args.p_action==='append'){const rows=entries[p.conversationId]||(entries[p.conversationId]=[]);data={id:rows.length+1,message:p.message,reply:p.reply,created_at:new Date().toISOString()};rows.push(data);}return {data,error:null};}} as unknown as SupabaseClient;
export default function TestPage(){return <CreateRecord client={client} type="fault" aircraft={[{prefix:"PR-TEST",model:"S92",base:"Teste"}]} people={[]} seed={{type:"fault",prefix:"PR-TEST",sourceFlightId:"test"}} user="TEST" canAssign={false} onClose={()=>{}} onCreate={async()=>{}}/>;}
